// ---- safe parsing helpers (fix: "12,500.00" -> NaN -> 0, currency 840 -> TypeError) ----
function parseAmount(raw) {
  if (raw === null || raw === undefined || raw === "") return NaN;
  if (typeof raw === "number") return Number.isFinite(raw) ? raw : NaN;
  if (typeof raw !== "string") return NaN;
  let s = raw.trim();
  if (s === "") return NaN;
  const negativeParens = /^\(.*\)$/.test(s);
  s = s.replace(/[()]/g, "");
  s = s.replace(/[\s\u00A0$\u20AC\u00A3\u00A5\u20AB]/g, "");   // spaces + currency symbols
  s = s.replace(/^[A-Za-z]{3}/, "");                        // leading ISO code e.g. "USD 1250"
  if (s === "") return NaN;
  if (/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(s))      s = s.replace(/,/g, "");            // 12,500.00
  else if (/^\d{1,3}(\.\d{3})+(,\d+)?$/.test(s)) s = s.replace(/\./g, "").replace(",", "."); // 12.500,00
  else if (/^\d+,\d{1,2}$/.test(s))              s = s.replace(",", ".");            // 1250,50
  else if (!/^\d+(\.\d+)?$/.test(s))             return NaN;                          // not a number at all
  const n = Number(s);
  if (!Number.isFinite(n)) return NaN;
  return negativeParens ? -n : n;
}
function requireText(v, field) {
  if (v === null || v === undefined) throw new Error("Missing required field: " + field);
  if (typeof v === "object") throw new Error("Invalid " + field + ": expected text, got object/array");
  const s = String(v).replace(/\s+/g, " ").trim();
  if (s === "") throw new Error("Missing required field: " + field);
  return s;
}
const norm = (s) => String(s).toUpperCase().replace(/\s+/g, " ").trim();

// ---- extract Gemini payload (keep previous shape handling) ----
const item = $input.first().json;
let data = item;
if (item.candidates && item.candidates[0] && item.candidates[0].content
    && item.candidates[0].content.parts && item.candidates[0].content.parts[0]
    && item.candidates[0].content.parts[0].text) {
  data = item.candidates[0].content.parts[0].text;
} else if (item.message && item.message.content) {
  data = item.message.content;
} else if (item.choices && item.choices[0] && item.choices[0].message && item.choices[0].message.content) {
  data = item.choices[0].message.content;
}
if (typeof data === "string") {
  data = data.replace(/^```(json)?\s*/i, "").replace(/\s*```$/i, "").trim();
  try { data = JSON.parse(data); }
  catch (e) { throw new Error("AI output is not valid JSON: " + e.message); }
}
if (typeof data !== "object" || data === null) {
  throw new Error("AI output is not a JSON object");
}

// ---- required fields + type safety ----
const vendor = requireText(data.vendor, "vendor");
const billTo = requireText(data.billTo, "billTo");
const invoiceNumber = requireText(data.invoiceNumber, "invoiceNumber");

// ---- amounts: must be real, finite, positive ----
const totalAmount = parseAmount(data.totalAmount);
if (!Number.isFinite(totalAmount)) {
  throw new Error("Invalid totalAmount: " + JSON.stringify(data.totalAmount)
    + " (expected a number, e.g. 12500.00 or \"12,500.00\")");
}
if (totalAmount <= 0) {
  throw new Error("Invalid totalAmount: must be > 0, got " + totalAmount);
}
const subtotalParsed = parseAmount(data.subtotal);
const taxAmount = (() => { const v = parseAmount(data.taxAmount); return Number.isFinite(v) ? v : 0; })();

// ---- line items ----
let lineItems = [];
if (data.lineItems !== undefined && data.lineItems !== null) {
  if (!Array.isArray(data.lineItems)) {
    throw new Error("Invalid lineItems: expected an array");
  }
  lineItems = data.lineItems.map((li) => ({
    description: String(li?.description ?? "").trim(),
    quantity: (() => { const v = parseAmount(li?.quantity); return Number.isFinite(v) ? v : null; })(),
    unitPrice: (() => { const v = parseAmount(li?.unitPrice); return Number.isFinite(v) ? v : null; })(),
    amount: (() => { const v = parseAmount(li?.amount); return Number.isFinite(v) ? v : 0; })(),
  }));
}
const calcSubtotal = lineItems.reduce((s, li) => s + li.amount, 0);

// ---- currency: force string + ISO-4217 shape (no more TypeError on numeric) ----
const currency = String(data.currency ?? "USD").trim().toUpperCase();
if (!/^[A-Z]{3}$/.test(currency)) {
  throw new Error("Invalid currency code: " + JSON.stringify(data.currency)
    + " (expected 3-letter ISO code, e.g. USD / EUR / VND)");
}

// ---- math check (unchanged rule) ----
const base = Number.isFinite(subtotalParsed) ? subtotalParsed : calcSubtotal;
const subtotal = Number.isFinite(subtotalParsed) ? subtotalParsed : calcSubtotal;
const calcTotal = base + taxAmount;
const mathOk = Math.abs(calcTotal - totalAmount) < 0.05;

// ---- dedup key: vendor+invoiceNumber is the real business key (invoice numbers repeat across vendors) ----
const dedupKey = norm(vendor) + "|" + norm(invoiceNumber);

return [{
  json: {
    dedupKey: dedupKey,
    vendor: vendor,
    billTo: billTo,
    invoiceNumber: invoiceNumber,
    invoiceDate: data.invoiceDate || null,
    dueDate: data.dueDate || null,
    poNumber: data.poNumber || null,
    paymentTerms: data.paymentTerms || null,
    currency: currency,
    subtotal: subtotal,
    taxRate: Number.isFinite(Number(data.taxRate)) ? Number(data.taxRate) : null,
    taxAmount: taxAmount,
    totalAmount: totalAmount,
    lineItems: lineItems,
    mathCheck: mathOk ? "OK" : "MISMATCH",
    status: mathOk ? "Pending" : "Needs Review",
    extractedAt: new Date().toISOString(),
  },
}];
